package com.cenedu.backend.domain.problem.authoring.semantic.evaluation;
import java.math.*;
public record SemanticNumber(BigInteger numerator,BigInteger denominator){public SemanticNumber{if(denominator.signum()==0)throw new ArithmeticException("zero denominator");if(denominator.signum()<0){numerator=numerator.negate();denominator=denominator.negate();}var g=numerator.gcd(denominator);numerator=numerator.divide(g);denominator=denominator.divide(g);}public static SemanticNumber parse(String s){if(s.contains("/")){var p=s.split("/",-1);return new SemanticNumber(new BigInteger(p[0]),new BigInteger(p[1]));}var d=new BigDecimal(s);return new SemanticNumber(d.unscaledValue(),BigInteger.TEN.pow(d.scale()));}public SemanticNumber add(SemanticNumber b){return new SemanticNumber(numerator.multiply(b.denominator).add(b.numerator.multiply(denominator)),denominator.multiply(b.denominator));}public SemanticNumber sub(SemanticNumber b){return add(b.neg());}public SemanticNumber mul(SemanticNumber b){return new SemanticNumber(numerator.multiply(b.numerator),denominator.multiply(b.denominator));}public SemanticNumber div(SemanticNumber b){return new SemanticNumber(numerator.multiply(b.denominator),denominator.multiply(b.numerator));}public SemanticNumber neg(){return new SemanticNumber(numerator.negate(),denominator);}public String canonical(){return denominator.equals(BigInteger.ONE)?numerator.toString():numerator+"/"+denominator;}}
